/// Tier recipes split by generated responsibility.
const TIERS_GROUPS_JUST: &str = include_str!("../../../templates/justfiles/anvil/groups/tiers.just");
const TIERS_HELPERS_JUST: &str = include_str!("../../../templates/justfiles/anvil/helpers/tiers.just");
const TIERS_SETUP_JUST: &str = include_str!("../../../templates/justfiles/anvil/setup/tiers.just");

/// Embedded body of the `anvil-imports` region in the user's Justfile.
pub(crate) const JUSTFILE_IMPORTS_BODY: &str = include_str!("../../../templates/regions/justfile-imports.just");

/// Region id for the imports block in the user's `Justfile`.
pub(crate) const JUSTFILE_REGION_ID: &str = "anvil-imports";

/// Canonical repo-root-relative path of the user's `Justfile`.
///
/// Capitalized to match the dominant Unix convention for repo-root
/// build-config files (`Makefile`, `Dockerfile`, `Rakefile`, ...). `just`
/// accepts either case, and the engine reuses whatever casing a repo already
/// has on disk.
pub(crate) const JUSTFILE_PATH: &str = "Justfile";

const JUSTFILE_SCAFFOLD: &str = "set unstable\n\
set windows-shell := [\"pwsh.exe\", \"-NoLogo\", \"-NoProfile\", \"-NonInteractive\", \"-Command\"]\n\n";

fn section(path: &'static str, id: impl Into<String>, body: impl Into<String>) -> Artifact {
    Artifact::owned_file_section(path, id, body.into().replace("\r\n", "\n"))
}

pub(crate) fn generated_header(path: &'static str, id: &'static str) -> Artifact {
    section(path, id, REPEATED_TEMPLATE_HEADER)
}

fn without_generated_header(body: &str) -> String {
    let normalized = body.replace("\r\n", "\n");
    normalized.strip_prefix(REPEATED_TEMPLATE_HEADER).unwrap_or(&normalized).to_owned()
}

pub(crate) fn template_section(output_path: &'static str, source: &str, body: &str) -> Artifact {
    section(output_path, format!("source:{source}"), without_generated_header(body))
}

fn file_sections(output_path: &'static str, files: &[(&str, &str)]) -> Vec<Artifact> {
    files
        .iter()
        .map(|&(source, body)| template_section(output_path, source, body))
        .collect()
}

/// Header and `anvil` alias for the composed recipe file.
#[must_use]
pub fn entry() -> Artifact {
    section(ANVIL_JUST_PATH, "alias:anvil", ENTRY_JUST)
}

/// Generated-content headers for the non-container composed recipe files.
#[must_use]
pub fn headers() -> Vec<Artifact> {
    vec![
        generated_header(CHECKS_JUST_PATH, "header:checks"),
        generated_header(GROUPS_JUST_PATH, "header:groups"),
        generated_header(HELPERS_JUST_PATH, "header:helpers"),
        generated_header(SETUP_JUST_PATH, "header:setup"),
    ]
}

/// One-time scaffold for a repository that has no root Justfile yet.
#[must_use]
pub(crate) const fn scaffold() -> &'static str {
    JUSTFILE_SCAFFOLD
}

/// Pinned toolchain and cargo-subcommand version declarations.
#[must_use]
pub fn versions() -> Vec<Artifact> {
    vec![template_section(
        SETUP_JUST_PATH,
        "justfiles/anvil/setup/versions.just",
        VERSIONS_JUST,
    )]
}

/// Tool install and prerequisite recipes.
#[must_use]
pub fn tools() -> Vec<Artifact> {
    vec![template_section(SETUP_JUST_PATH, "justfiles/anvil/setup/tools.just", TOOLS_JUST)]
}

/// Shared private helper recipes and definitions.
#[must_use]
pub fn helpers() -> Vec<Artifact> {
    vec![template_section(
        HELPERS_JUST_PATH,
        "justfiles/anvil/helpers/common.just",
        HELPERS_JUST,
    )]
}

/// Public impact command plus its shared selection definitions.
#[must_use]
pub fn impact() -> Vec<Artifact> {
    vec![
        template_section(HELPERS_JUST_PATH, "justfiles/anvil/helpers/impact.just", IMPACT_HELPERS_JUST),
        template_section(CHECKS_JUST_PATH, "justfiles/anvil/checks/impact.just", IMPACT_CHECK_JUST),
    ]
}

/// Generic local-development recipe files.
#[must_use]
pub fn dev_files() -> Vec<Artifact> {
    file_sections(CHECKS_JUST_PATH, DEV_CHECK_FILES)
        .into_iter()
        .chain(file_sections(SETUP_JUST_PATH, DEV_SETUP_FILES))
        .collect()
}

/// Check execution, helper, and setup templates, each mapped directly to its
/// generated responsibility file.
#[must_use]
pub fn check_files() -> Vec<Artifact> {
    file_sections(CHECKS_JUST_PATH, CHECK_FILES)
        .into_iter()
        .chain(file_sections(HELPERS_JUST_PATH, CHECK_HELPER_FILES))
        .chain(file_sections(SETUP_JUST_PATH, CHECK_SETUP_FILES))
        .collect()
}

/// Group execution, helper, and setup templates, each mapped directly to its
/// generated responsibility file.
#[must_use]
pub fn group_files() -> Vec<Artifact> {
    file_sections(GROUPS_JUST_PATH, GROUP_FILES)
        .into_iter()
        .chain(file_sections(HELPERS_JUST_PATH, GROUP_HELPER_FILES))
        .chain(file_sections(SETUP_JUST_PATH, GROUP_SETUP_FILES))
        .collect()
}

/// Tier aggregators, private fan-out helpers, and setup recipes.
#[must_use]
pub fn tiers() -> Vec<Artifact> {
    vec![
        template_section(GROUPS_JUST_PATH, "justfiles/anvil/groups/tiers.just", TIERS_GROUPS_JUST),
        template_section(HELPERS_JUST_PATH, "justfiles/anvil/helpers/tiers.just", TIERS_HELPERS_JUST),
        template_section(SETUP_JUST_PATH, "justfiles/anvil/setup/tiers.just", TIERS_SETUP_JUST),
    ]
}

/// Look up one built-in Just source section by its template path.
#[must_use]
pub fn source(path: &str) -> Option<Artifact> {
    let id = format!("source:{path}");
    tools()
        .into_iter()
        .chain(versions())
        .chain(helpers())
        .chain(impact())
        .chain(tiers())
        .chain(dev_files())
        .chain(check_files())
        .chain(group_files())
        .find(|artifact| {
            matches!(
                artifact,
                Artifact::OwnedFileSection(section) if section.id == id
            )
        })
}

#[cfg(test)]
#[cfg_attr(coverage_nightly, coverage(off))]
mod tests {
    use std::collections::{BTreeMap, BTreeSet};
    use std::process::Command;

    use tempfile::TempDir;

    use super::*;
    use crate::Catalog;

    #[cfg_attr(miri, ignore = "spawns just; miri isolation forbids it")]
    #[test]
    fn composed_justfile_parses() {
        let mut files = BTreeMap::<&str, String>::new();
        for artifact in Catalog::anvil().artifacts() {
            let Artifact::OwnedFileSection(section) = artifact else {
                continue;
            };
            if !std::path::Path::new(section.path)
                .extension()
                .is_some_and(|extension| extension.eq_ignore_ascii_case("just"))
            {
                continue;
            }
            let body = files.entry(section.path).or_default();
            if !body.is_empty() {
                body.push_str("\n\n");
            }
            body.push_str(section.body.trim_matches(['\r', '\n']));
            body.push('\n');
        }
        assert_eq!(
            files
                .values()
                .map(|body| body
                    .matches("GENERATED BY cargo-anvil. DO NOT EDIT DIRECTLY unless you intend to depart from anvil-provided defaults.")
                    .count())
                .sum::<usize>(),
            7,
            "each generated recipe file must carry one generated-content header"
        );
        let temp = TempDir::new().expect("temporary Justfile directory must be creatable");
        for (relative, body) in files {
            let path = temp.path().join(relative);
            std::fs::create_dir_all(path.parent().expect("generated recipe path has a parent"))
                .expect("generated recipe directory must be creatable");
            std::fs::write(path, body).expect("composed Justfile fixture must be writable");
        }
        let root = temp.path().join("Justfile");
        std::fs::write(
            &root,
            "set unstable\nset windows-shell := [\"pwsh\", \"-NoProfile\", \"-Command\"]\nimport '.anvil/anvil.just'\n",
        )
        .expect("root Justfile fixture must be writable");

        let output = Command::new("just")
            .args(["--justfile"])
            .arg(&root)
            .arg("--dump")
            .output()
            .expect("just must be available for generated-recipe tests");
        assert!(
            output.status.success(),
            "composed Justfile did not parse:\n{}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn source_templates_are_independently_addressable_catalog_sections() {
        let artifact = source("justfiles/anvil/checks/clippy.just").expect("the clippy source section must be addressable");
        let Artifact::OwnedFileSection(section) = artifact else {
            panic!("a Just source must be an owned-file section");
        };
        assert_eq!(section.path, CHECKS_JUST_PATH);
        assert_eq!(section.id, "source:justfiles/anvil/checks/clippy.just");
        assert!(section.body.contains("anvil-clippy:"));
        assert!(!section.body.contains("anvil-clippy-setup"));
    }

    #[test]
    fn source_sections_are_replaceable_without_affecting_neighbors() {
        let tools = source("justfiles/anvil/setup/tools.just").expect("the tools source section must be addressable");
        let Artifact::OwnedFileSection(section) = &tools else {
            panic!("a Just source must be an owned-file section");
        };
        assert_eq!(section.path, SETUP_JUST_PATH);
        assert_eq!(section.id, "source:justfiles/anvil/setup/tools.just");
        assert!(section.body.contains("_install-component toolchain component:"));

        let neighbor = source("justfiles/anvil/setup/checks/clippy.just").expect("the neighboring clippy setup source must be addressable");
        let replacement = tools.with_body("_install-component toolchain component:\n    echo replaced\n");
        let catalog = Catalog::anvil().into_builder().replace_artifact(replacement).build().unwrap();
        let replaced = catalog
            .artifacts()
            .iter()
            .find(|artifact| {
                matches!(
                    artifact,
                    Artifact::OwnedFileSection(section)
                        if section.path == SETUP_JUST_PATH
                            && section.id == "source:justfiles/anvil/setup/tools.just"
                )
            })
            .expect("the replacement must retain the source identity");
        let unchanged_neighbor = catalog
            .artifacts()
            .iter()
            .find(|artifact| {
                matches!(
                    artifact,
                    Artifact::OwnedFileSection(section)
                        if section.path == SETUP_JUST_PATH
                            && section.id == "source:justfiles/anvil/setup/checks/clippy.just"
                )
            })
            .expect("the neighboring source must remain present");
        assert!(replaced.body().contains("echo replaced"));
        assert_eq!(unchanged_neighbor.body(), neighbor.body());
    }

    #[test]
    fn source_section_ids_are_unique() {
        let mut ids = BTreeSet::new();
        for artifact in tools()
            .into_iter()
            .chain(versions())
            .chain(helpers())
            .chain(impact())
            .chain(tiers())
            .chain(dev_files())
            .chain(check_files())
            .chain(group_files())
        {
            let Artifact::OwnedFileSection(section) = artifact else {
                continue;
            };
            assert!(ids.insert(section.id.clone()), "duplicate Just section id: {}", section.id);
        }
    }

    #[test]
    fn source_layout_determines_generated_responsibility() {
        for (source_path, expected_path) in [
            ("justfiles/anvil/checks/aprz.just", CHECKS_JUST_PATH),
            ("justfiles/anvil/setup/checks/aprz.just", SETUP_JUST_PATH),
            ("justfiles/anvil/helpers/checks/miri.just", HELPERS_JUST_PATH),
            ("justfiles/anvil/groups/pr-fast.just", GROUPS_JUST_PATH),
            ("justfiles/anvil/setup/groups/pr-fast.just", SETUP_JUST_PATH),
            ("justfiles/anvil/helpers/groups/scheduled-test.just", HELPERS_JUST_PATH),
        ] {
            let artifact = source(source_path).unwrap_or_else(|| panic!("{source_path} must be independently addressable"));
            assert!(
                matches!(artifact, Artifact::OwnedFileSection(section) if section.path == expected_path),
                "{source_path} must be emitted to {expected_path}"
            );
        }
    }

    #[test]
    fn every_registered_source_maps_to_one_section() {
        for (source_path, _) in CHECK_FILES
            .iter()
            .chain(CHECK_HELPER_FILES)
            .chain(CHECK_SETUP_FILES)
            .chain(DEV_CHECK_FILES)
            .chain(DEV_SETUP_FILES)
            .chain(GROUP_FILES)
            .chain(GROUP_HELPER_FILES)
            .chain(GROUP_SETUP_FILES)
        {
            let artifact = source(source_path).unwrap_or_else(|| panic!("{source_path} must be registered"));
            assert!(
                matches!(artifact, Artifact::OwnedFileSection(section) if section.id == format!("source:{source_path}")),
                "{source_path} must map to exactly one source section"
            );
        }
    }
}
